enum Route: Hashable {
  case post(id: String)
  case comment(postID: String, commentID: String)
  case settings
}

@Observable
final class Router {
  var path: [Route] = []
  var pendingAfterLogin: Route?

  func open(_ route: Route, signedIn: Bool) {
    guard signedIn else { pendingAfterLogin = route; return }
    switch route {
    case let .comment(postID, commentID):
      // Rebuild the whole stack at once, not push by push
      path = [.post(id: postID), .comment(postID: postID, commentID: commentID)]
    default:
      path = [route]
    }
  }
}

struct RootView: View {
  @State private var router = Router()

  var body: some View {
    NavigationStack(path: $router.path) {
      FeedView()
        .navigationDestination(for: Route.self) { route in
          switch route {
          case let .post(id): PostView(id: id)
          case let .comment(postID, commentID): CommentView(postID: postID, id: commentID)
          case .settings: SettingsView()
          }
        }
    }
    .onOpenURL { url in
      if let route = RouteParser.parse(url) {
        router.open(route, signedIn: Session.shared.isSignedIn)
      }
    }
  }
}

// Domain — no framework types, trivially testable
struct Article: Identifiable, Equatable {
  let id: String
  let title: String
  let body: String
}

protocol ArticleRepository {
  func latest() async throws -> [Article]
}

// Data layer — network and store hidden behind the same protocol
struct DefaultArticleRepository: ArticleRepository {
  let api: APIClient
  let store: ArticleStore

  func latest() async throws -> [Article] {
    do {
      let fresh = try await api.get([ArticleDTO].self, path: "/articles").map(Article.init)
      try await store.replaceAll(fresh)
      return fresh
    } catch let error as URLError where error.code == .notConnectedToInternet {
      return try await store.all()
    }
  }
}

// Use case — pulls its weight because it spans two repositories
struct PublishDraft {
  let articles: ArticleRepository
  let drafts: DraftRepository

  func callAsFunction(draftID: String) async throws -> Article {
    let draft = try await drafts.load(id: draftID)
    guard !draft.title.isEmpty else { throw DomainError.emptyTitle }
    let article = try await articles.publish(draft)
    try await drafts.delete(id: draftID)
    return article
  }
}

