// Real logic — a model earns its place and is testable without a view
@Observable
final class SignUpModel {
  var email = ""
  var password = ""
  private(set) var isSubmitting = false
  private(set) var error: String?

  private let accounts: AccountService
  init(accounts: AccountService) { self.accounts = accounts }

  var canSubmit: Bool { email.contains("@") && password.count >= 8 && !isSubmitting }

  func submit() async {
    guard canSubmit else { return }
    isSubmitting = true
    defer { isSubmitting = false }
    do { try await accounts.register(email: email, password: password) }
    catch { self.error = String(describing: error) }
  }
}

struct SignUpView: View {
  @State private var model: SignUpModel

  init(accounts: AccountService) {
    _model = State(initialValue: SignUpModel(accounts: accounts))
  }

  var body: some View {
    Form {
      TextField("Email", text: $model.email)
      SecureField("Password", text: $model.password)
      Button("Create account") { Task { await model.submit() } }
        .disabled(!model.canSubmit)
    }
  }
}

// UIKit pushes a SwiftUI screen; the coordinator still owns navigation
final class SettingsCoordinator {
  private let nav: UINavigationController
  private let session: SessionStore          // @Observable, shared by both worlds

  init(nav: UINavigationController, session: SessionStore) {
    self.nav = nav
    self.session = session
  }

  func start() {
    let view = SettingsView(session: session, onSignOut: { [weak self] in self?.signOut() })
    let host = UIHostingController(rootView: view)
    host.title = "Settings"
    nav.pushViewController(host, animated: true)
  }

  private func signOut() {
    session.signOut()
    nav.popToRootViewController(animated: true)
  }
}

