// Before — untestable: the dependency is fetched, not received
final class FeedViewController: UIViewController {
  private var posts: [Post] = []

  func load() {
    Task { posts = (try? await NetworkManager.shared.feed()) ?? [] }
  }
}

// Step 1 — a protocol over the existing singleton
protocol FeedFetching {
  func feed() async throws -> [Post]
}
extension NetworkManager: FeedFetching {}

// Step 2 — inject with a default so existing call sites keep compiling
final class FeedPresenter {
  private let network: FeedFetching
  private(set) var posts: [Post] = []

  init(network: FeedFetching = NetworkManager.shared) {
    self.network = network
  }

  func load() async {
    posts = (try? await network.feed()) ?? []
  }
}

